#!/usr/bin/env node
// Headroom dogfood toggle — route the REAL daily-driver Pi fork through Headroom.
//
// Chain when on:
//   pi (fork) -> headroom :8791 (--mode cache) -> claude-bridge :9100 (live) -> Anthropic
//
// `on`     start Headroom, point ~/.pi/agent/models.json claude-bridge baseUrl at it
// `off`    stop Headroom, restore the original baseUrl
// `status` show savings from the dogfood log
//
// No sandbox, no temp bridge, no config copies. Reversible in one command.
// After `on`/`off`, start a NEW Pi session (models.json is read at launch).

import { spawn } from "node:child_process";
import { mkdirSync, openSync, readFileSync, writeFileSync, existsSync, unlinkSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const HEADROOM_PORT = Number(process.env.HEADROOM_PORT || 8791);
const HEADROOM_URL = `http://127.0.0.1:${HEADROOM_PORT}`;
const BRIDGE_URL = process.env.PI_BRIDGE_URL || "http://127.0.0.1:9100";
const HEADROOM_BIN = process.env.HEADROOM_BIN || "headroom";

const MODELS_PATH = join(homedir(), ".pi/agent/models.json");
const HR_DIR = join(homedir(), ".headroom");
const LOG_PATH = join(HR_DIR, "logs/pi-dogfood.log");
const PID_PATH = join(HR_DIR, "dogfood.pid");
const STATE_PATH = join(HR_DIR, "dogfood-state.json");

function readJson(p) {
  return JSON.parse(readFileSync(p, "utf8"));
}
function writeJson(p, obj) {
  writeFileSync(p, `${JSON.stringify(obj, null, 2)}\n`);
}
function setBridgeBaseUrl(url) {
  const models = readJson(MODELS_PATH);
  const bridge = models.providers?.["claude-bridge"];
  if (!bridge) throw new Error("claude-bridge provider missing from models.json");
  const prev = bridge.baseUrl;
  bridge.baseUrl = url;
  writeJson(MODELS_PATH, models);
  return prev;
}
function isAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

async function waitHealthy(deadlineMs = 30_000) {
  const end = Date.now() + deadlineMs;
  while (Date.now() < end) {
    try {
      const r = await fetch(`${HEADROOM_URL}/health`).catch(() => null);
      if (r && r.ok) return true;
    } catch {}
    await new Promise((r) => setTimeout(r, 300));
  }
  return false;
}

async function on() {
  if (existsSync(PID_PATH)) {
    const pid = Number(readFileSync(PID_PATH, "utf8").trim());
    if (isAlive(pid)) {
      console.log(`Headroom dogfood already running (pid ${pid}). Run 'off' first to restart.`);
      return;
    }
    unlinkSync(PID_PATH);
  }
  mkdirSync(join(HR_DIR, "logs"), { recursive: true });

  const out = openSync(LOG_PATH.replace(/\.log$/, ".proc.log"), "a");
  // Cache-safe optimizer set: compress NEW large tool outputs without rewriting
  // history (--mode cache freezes prior turns to protect the bridge's prompt
  // cache). --code-aware = AST compression of code; --intercept-tool-results =
  // ast-grep Read outliner. Memory/code-graph are intentionally OFF: they mutate
  // tools[]/system and would break the bridge's byte-stable cache prefix.
  const args = [
    "proxy",
    "--mode",
    "cache",
    "--port",
    String(HEADROOM_PORT),
    "--anthropic-api-url",
    BRIDGE_URL,
    "--code-aware",
    "--intercept-tool-results",
    "--no-telemetry",
    "--log-file",
    LOG_PATH,
    ...(process.env.HEADROOM_EXTRA_ARGS ? process.env.HEADROOM_EXTRA_ARGS.split(/\s+/).filter(Boolean) : []),
  ];
  const child = spawn(HEADROOM_BIN, args, {
    detached: true,
    stdio: ["ignore", out, out],
    env: { ...process.env, HEADROOM_MODE: "cache", HEADROOM_TELEMETRY: "off", HEADROOM_CODE_AWARE_ENABLED: "1" },
  });
  child.unref();
  writeFileSync(PID_PATH, String(child.pid));

  process.stdout.write(`Starting Headroom (cache mode) on ${HEADROOM_URL} -> ${BRIDGE_URL} ... `);
  const ok = await waitHealthy();
  if (!ok) {
    console.log("FAILED");
    console.error(`Headroom did not become healthy. Check ${LOG_PATH.replace(/\.log$/, ".proc.log")}`);
    process.exit(1);
  }
  console.log("up");

  const prevBaseUrl = setBridgeBaseUrl(HEADROOM_URL);
  writeJson(STATE_PATH, { pid: child.pid, prevBaseUrl, startedAt: new Date().toISOString() });

  console.log(`\nclaude-bridge baseUrl: ${prevBaseUrl} -> ${HEADROOM_URL}`);
  console.log("Start a NEW Pi session for it to take effect.");
  console.log("Guardrails: keep to Haiku/Sonnet first; run 'npm run headroom:off' to revert instantly.");
}

async function off() {
  // Restore baseUrl for NEW sessions, but DO NOT kill Headroom. Pi caches the
  // provider baseUrl per session, so any live session that already picked up
  // :8791 would be stranded on a dead port if we killed the proxy here. Leaving
  // Headroom up as a transparent passthrough keeps those sessions alive while
  // new sessions go direct. Use `stop` to actually kill the proxy.
  let state = {};
  if (existsSync(STATE_PATH)) state = readJson(STATE_PATH);
  const restore = state.prevBaseUrl || BRIDGE_URL;
  try {
    const cur = setBridgeBaseUrl(restore);
    console.log(`claude-bridge baseUrl: ${cur} -> ${restore} (new sessions go direct)`);
  } catch (e) {
    console.error(`Could not restore baseUrl: ${e.message}`);
  }
  const pid = state.pid || (existsSync(PID_PATH) ? Number(readFileSync(PID_PATH, "utf8").trim()) : 0);
  if (pid && isAlive(pid)) {
    console.log(`Headroom still running (pid ${pid}) as a passthrough so live sessions on :8791 keep working.`);
    console.log("When no session uses it: npm run headroom:stop");
  } else {
    console.log("Headroom is not running.");
  }
}

async function stop() {
  let state = {};
  if (existsSync(STATE_PATH)) state = readJson(STATE_PATH);
  const bridge = readJson(MODELS_PATH).providers?.["claude-bridge"]?.baseUrl;
  if (bridge === HEADROOM_URL) {
    console.error(`Refusing to stop: claude-bridge baseUrl still points at Headroom (${HEADROOM_URL}).`);
    console.error("Run 'npm run headroom:off' first, then start a new Pi session, then stop.");
    process.exit(1);
  }
  const pid = state.pid || (existsSync(PID_PATH) ? Number(readFileSync(PID_PATH, "utf8").trim()) : 0);
  if (pid && isAlive(pid)) {
    try {
      process.kill(pid, "SIGTERM");
    } catch {}
    console.log(`Stopped Headroom (pid ${pid}).`);
  } else {
    console.log("No running Headroom dogfood process found.");
  }
  for (const p of [PID_PATH, STATE_PATH]) if (existsSync(p)) unlinkSync(p);
}

function quantile(v, q) {
  if (!v.length) return 0;
  const s = [...v].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.max(0, Math.ceil(q * s.length) - 1))];
}

function status() {
  const running = existsSync(PID_PATH) && isAlive(Number(readFileSync(PID_PATH, "utf8").trim()));
  const bridge = readJson(MODELS_PATH).providers?.["claude-bridge"]?.baseUrl;
  console.log(`Headroom dogfood: ${running ? "ON" : "off"}`);
  console.log(`claude-bridge baseUrl: ${bridge}`);
  if (!existsSync(LOG_PATH)) {
    console.log("No dogfood log yet — run some real sessions while ON.");
    return;
  }
  const rows = readFileSync(LOG_PATH, "utf8")
    .split("\n")
    .filter(Boolean)
    .map((l) => {
      try {
        return JSON.parse(l);
      } catch {
        return null;
      }
    })
    .filter(Boolean);
  const t = rows.reduce(
    (a, r) => {
      a.original += Number(r.input_tokens_original || 0);
      a.saved += Number(r.tokens_saved || 0);
      a.lat.push(Number(r.total_latency_ms || 0));
      if (r.cache_hit) a.hits += 1;
      return a;
    },
    { original: 0, saved: 0, lat: [], hits: 0 },
  );
  const pct = t.original > 0 ? (t.saved / t.original) * 100 : 0;
  console.log(
    JSON.stringify(
      {
        requests: rows.length,
        inputTokensOriginal: t.original,
        tokensSaved: t.saved,
        savingsPercent: Number(pct.toFixed(2)),
        cacheHits: t.hits,
        latencyMs: { p50: quantile(t.lat, 0.5), p95: quantile(t.lat, 0.95) },
      },
      null,
      2,
    ),
  );
}

const cmd = process.argv[2];
const run = { on, off, stop, status }[cmd];
if (!run) {
  console.error("usage: headroom-dogfood.mjs <on|off|stop|status>");
  process.exit(2);
}
Promise.resolve(run()).catch((e) => {
  console.error(e?.stack || e);
  process.exit(1);
});

