async function probeGlobalCacheScope() {
  if (!GLOBAL_CACHE || authMode === "apikey") return;
  try {
    const token = await getAccessToken();
    if (!token) { console.error("[GLOBAL-CACHE] no OAuth token; global scope stays off"); return; }
    const res = await postProbeWithUpstreamAgent(
      {
        "content-type": "application/json",
        "anthropic-version": ANTHROPIC_VERSION,
        "authorization": `Bearer ${token}`,
        "anthropic-beta": [...baseOAuthCacheBetas(), GLOBAL_SCOPE_BETA].join(","),
        "user-agent": `claude-cli/${CLAUDE_CLI_VERSION}`,
        "x-app": "cli",
      },
      {
        model: "claude-opus-4-8", max_tokens: 1,
        system: [{ type: "text", text: "You are Claude Code, Anthropic's official CLI for Claude.", cache_control: { ...EPHEMERAL, scope: "global" } }],
        messages: [{ role: "user", content: "hi" }],
      },
    );
    if (res.status === 200) {
      globalScopeConfirmed = true;
      console.log("[GLOBAL-CACHE] enabled: scope:\"global\" accepted on the static system prefix");
    } else {
      const msg = res.json?.error?.message || "";
      console.error(`[GLOBAL-CACHE] disabled: Anthropic rejected scope (HTTP ${res.status}: ${msg.slice(0, 120)})`);
    }
  } catch (err) {
    console.error(`[GLOBAL-CACHE] disabled: probe failed (${err.message})`);
  }
}

