/**
 * Cross-session global cache (cache_control.scope:"global") tests.
 *
 * Verifies the BRIDGE_GLOBAL_CACHE opt-in: the byte-stable system-context core
 * (block 0 of the moved <system-context>) is marked scope:"global" so every session
 * reads one shared Anthropic cache entry, while the dynamic tail stays org-scoped —
 * matching Claude Code's static-prefix treatment. Also verifies the boot probe is
 * fail-closed-until-confirmed (global scope stays off until a 200), that the probe
 * sends the SAME beta set as live traffic (so it can't 400 on ttl and self-disable),
 * and that a rejected probe disables global scope instead of 400-ing all traffic.
 *
 * Hermetic: dummy _BRIDGE_OAUTH_TOKEN (no keychain) + a mock upstream. Spawns the
 * bridge per scenario because index.js caches a single in-process boot/probe.
 */
import http from "node:http";
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = dirname(fileURLToPath(import.meta.url));
const SCOPE_BETA = "prompt-caching-scope-2026-01-05";
let failures = 0;
function assert(cond, msg) {
  if (cond) console.log(`  PASS: ${msg}`);
  else { console.error(`  FAIL: ${msg}`); failures++; }
}

function startMock(port, { rejectProbe = false, delayProbeMs = 0 } = {}) {
  let real = null;
  let probe = null;
  const server = http.createServer((req, res) => {
    let body = ""; req.on("data", (c) => (body += c));
    req.on("end", () => {
      let j = null; try { j = JSON.parse(body); } catch {}
      const beta = req.headers["anthropic-beta"] || "";
      const isProbe = j?.system?.[0]?.text?.startsWith("You are Claude Code") && j?.messages?.[0]?.content === "hi";
      const reject = (message) => {
        res.writeHead(400, { "content-type": "application/json" });
        res.end(JSON.stringify({ type: "error", error: { type: "invalid_request_error", message } }));
      };
      if (isProbe) {
        probe = { beta, cache_control: j?.system?.[0]?.cache_control || null };
        if (rejectProbe) { reject("cache_control.ephemeral.scope: Extra inputs are not permitted"); return; }
        // Emulate Anthropic's beta-gated schema: a cache_control field is rejected
        // unless its gating beta rides along. This is exactly what 400s a probe that
        // sends ttl:"1h" without extended-cache-ttl-2025-04-11 (the regression guard
        // for the probe/live beta-drift bug).
        const cc = j?.system?.[0]?.cache_control || {};
        if (cc.ttl && !beta.includes("extended-cache-ttl-2025-04-11")) { reject("cache_control.ttl: Extra inputs are not permitted"); return; }
        if (cc.scope && !beta.includes(SCOPE_BETA)) { reject("cache_control.scope: Extra inputs are not permitted"); return; }
      }
      const respond = () => {
        if (!isProbe) real = { body: j, beta };
        res.writeHead(200, { "content-type": "application/json" });
        res.end(JSON.stringify({ id: "m", type: "message", role: "assistant", content: [{ type: "text", text: "ok" }], model: j?.model || "x", stop_reason: "end_turn", usage: { input_tokens: 1, output_tokens: 1 } }));
      };
      if (isProbe && delayProbeMs > 0) { setTimeout(respond, delayProbeMs); return; }
      respond();
    });
  });
  return new Promise((resolve) => server.listen(port, "127.0.0.1", () => resolve({ server, getReal: () => real, getProbe: () => probe })));
}

async function bootBridge(bridgePort, mockPort, waitMs = 2200) {
  const env = { ...process.env, PORT: String(bridgePort), HOST: "127.0.0.1", BRIDGE_GLOBAL_CACHE: "1", _BRIDGE_OAUTH_TOKEN: "sk-ant-oat-test-token", ANTHROPIC_BASE_URL: `http://127.0.0.1:${mockPort}` };
  delete env.ANTHROPIC_API_KEY;
  const child = spawn(process.execPath, [join(ROOT, "index.js")], { cwd: ROOT, env, stdio: ["ignore", "pipe", "pipe"] });
  let log = ""; child.stdout.on("data", (d) => (log += d)); child.stderr.on("data", (d) => (log += d));
  await new Promise((r) => setTimeout(r, waitMs)); // boot + (usually) startup probe
  return { child, getLog: () => log };
}

const piPayload = () => ({
  model: "claude-opus-4-8", max_tokens: 1, stream: false,
  system: [
    { type: "text", text: "You are Claude Code, Anthropic's official CLI for Claude." },
    { type: "text", text: "STABLE-CORE ".repeat(400), cache_control: { type: "ephemeral", ttl: "1h" } },
    { type: "text", text: "DYNAMIC-TAIL cwd + date" },
  ],
  messages: [{ role: "user", content: "hello" }],
});

async function send(port) {
  await fetch(`http://127.0.0.1:${port}/v1/messages`, { method: "POST", headers: { "content-type": "application/json", "anthropic-version": "2023-06-01" }, body: JSON.stringify(piPayload()) }).then((r) => r.text()).catch(() => {});
  await new Promise((r) => setTimeout(r, 350));
}

console.log("=== Global cache scope: happy path ===");
{
  const { server, getReal, getProbe } = await startMock(9502);
  const { child, getLog } = await bootBridge(9399, 9502);
  await send(9399);
  child.kill("SIGTERM"); server.close();
  assert(/GLOBAL-CACHE\] enabled/.test(getLog()), "boot probe accepted scope -> enabled");
  assert((getProbe()?.beta || "").includes("extended-cache-ttl-2025-04-11"), "probe carries extended-cache-ttl beta (matches its own ttl:1h cache_control)");
  assert((getProbe()?.beta || "").includes(SCOPE_BETA), "probe carries the scope gating beta");
  const ctx = (getReal()?.body?.messages || []).find((m) => m.role === "user" && Array.isArray(m.content) && m.content[0]?.text?.includes("<system-context>"));
  assert(!!ctx, "moved <system-context> present as user message[0]");
  assert(ctx?.content?.[0]?.cache_control?.scope === "global", "stable-core (block 0) is scope:global");
  assert(ctx?.content?.[0]?.cache_control?.type === "ephemeral", "stable-core stays ephemeral");
  const last = ctx?.content?.[ctx.content.length - 1];
  assert(ctx && ctx.content.length > 1 ? last?.cache_control?.scope !== "global" : true, "dynamic tail is NOT scope:global (org)");
  assert((getReal()?.beta || "").includes(SCOPE_BETA), "gating beta sent");
}

console.log("\n=== Global cache scope: safety gate on rejection ===");
{
  const { server, getReal } = await startMock(9503, { rejectProbe: true });
  const { child, getLog } = await bootBridge(9398, 9503);
  await send(9398);
  child.kill("SIGTERM"); server.close();
  assert(/GLOBAL-CACHE\] disabled/.test(getLog()), "boot probe rejection -> disabled");
  const ctx = (getReal()?.body?.messages || []).find((m) => m.role === "user" && Array.isArray(m.content));
  const anyScope = ctx ? ctx.content.some((b) => b?.cache_control?.scope === "global") : false;
  assert(!anyScope, "after disable, no block carries scope:global");
  assert(!(getReal()?.beta || "").includes(SCOPE_BETA), "after disable, gating beta not sent");
}

console.log("\n=== Global cache scope: fail-closed during probe flight (no 400 race) ===");
{
  // Hold the probe response 2000ms while the bridge starts accepting traffic almost
  // immediately. A request that lands BEFORE the probe confirms must be org-scoped —
  // never global, never the gating beta — proving there is no window where a dropped
  // beta could 400 live traffic.
  const { server, getReal } = await startMock(9504, { delayProbeMs: 2000 });
  const { child } = await bootBridge(9397, 9504, 500); // return before the probe resolves
  await send(9397);
  child.kill("SIGTERM"); server.close();
  const ctx = (getReal()?.body?.messages || []).find((m) => m.role === "user" && Array.isArray(m.content));
  assert(!!ctx, "in-flight request reached upstream during probe");
  const anyScope = ctx ? ctx.content.some((b) => b?.cache_control?.scope === "global") : false;
  assert(!anyScope, "request during probe flight is NOT global-scoped (fail-closed)");
  assert(!(getReal()?.beta || "").includes(SCOPE_BETA), "request during probe flight omits the gating beta");
}

console.log(failures ? `\n${failures} assertion(s) FAILED` : "\nAll global-cache-scope tests passed");
process.exit(failures ? 1 : 0);

