// True-prefix guard for cross-session global scope. Anthropic renders blocks
// tools -> system -> messages and requires every cache_control block that
// precedes a scope:"global" one to ALSO be scope:"global" (else: "scope:global
// ... is not a true prefix when tools are present"). The OAuth wrap marks the
// byte-stable <system-context> core scope:"global", and that core lives in
// messages[0] — AFTER the tools. So whenever a downstream block is globally
// scoped, the tools breakpoint that renders before it must be global too, or the
// request 400s. Detect a global block in system/messages so the tools marker can
// match it.
function hasGlobalScopedBlock(params) {
  const scan = (arr) => Array.isArray(arr) && arr.some((b) => b?.cache_control?.scope === "global");
  if (scan(params.system)) return true;
  if (Array.isArray(params.messages)) {
    for (const m of params.messages) if (scan(m?.content)) return true;
  }
  return false;
}

