(async()=>{
  let healthy=false;
  for(let i=0;i<20;i++){ if(await get("http://127.0.0.1:9100/health")===200){healthy=true;break;} await new Promise(r=>setTimeout(r,750)); }
  console.log("health:",healthy?"OK":"NOT-READY");
  // give the probe up to ~6s after healthy to resolve
  let verdict=null;
  for(let i=0;i<10;i++){
    const lines=fs.readFileSync(LOG,"utf8").split("\n");
    // find last "listening" then the GLOBAL-CACHE line after it
    let lastListen=-1; lines.forEach((l,k)=>{ if(l.includes("Claude Bridge listening")) lastListen=k; });
    const after=lines.slice(lastListen);
    const gc=after.find(l=>l.includes("[GLOBAL-CACHE]"));
    if(gc){verdict=gc;break;}
    await new Promise(r=>setTimeout(r,700));
  }
  console.log("boot line:", fs.readFileSync(LOG,"utf8").split("\n").filter(l=>l.includes("Claude Bridge listening")).pop());
  console.log("GLOBAL-CACHE verdict:", verdict||"(not logged yet)");
})();
