1	/**
2	 * Cross-session global cache (cache_control.scope:"global") tests.
3	 *
4	 * Verifies the BRIDGE_GLOBAL_CACHE opt-in: the byte-stable system-context core
5	 * (block 0 of the moved <system-context>) is marked scope:"global" so every session
6	 * reads one shared Anthropic cache entry, while the dynamic tail stays org-scoped —
7	 * matching Claude Code's static-prefix treatment. Also verifies the boot probe is
8	 * fail-closed-until-confirmed (global scope stays off until a 200), that the probe
9	 * sends the SAME beta set as live traffic (so it can't 400 on ttl and self-disable),
10	 * and that a rejected probe disables global scope instead of 400-ing all traffic.
11	 *
12	 * Hermetic: dummy _BRIDGE_OAUTH_TOKEN (no keychain) + a mock upstream. Spawns the
13	 * bridge per scenario because index.js caches a single in-process boot/probe.
14	 */
15	import http from "node:http";
16	import { spawn } from "node:child_process";
17	import { fileURLToPath } from "node:url";
18	import { dirname, join } from "node:path";
19	
20	const ROOT = dirname(fileURLToPath(import.meta.url));
21	const SCOPE_BETA = "prompt-caching-scope-2026-01-05";
22	let failures = 0;
23	function assert(cond, msg) {
24	  if (cond) console.log(`  PASS: ${msg}`);
25	  else { console.error(`  FAIL: ${msg}`); failures++; }
26	}
27	
28	// Anthropic's global-prefix rule: a scope:"global" cache_control block must not
29	// be preceded — in render order tools -> system -> messages — by any cache_control
30	// block with a narrower (org) scope. Tool definitions render before system, so an
31	// org-scoped tools breakpoint sitting in front of a global system/<system-context>
32	// block is exactly the live 400 ("...not a true prefix when tools are present").
33	// The toolless probe + toolless fixture never exercised this; this helper lets the
34	// mock fail the test the moment production emits a global marker after an org one.
35	function globalPrefixViolation(j) {
36	  const scopes = [];
37	  const push = (b) => { if (b?.cache_control) scopes.push(b.cache_control.scope === "global" ? "global" : "org"); };
38	  if (Array.isArray(j?.tools)) for (const t of j.tools) push(t);
39	  if (Array.isArray(j?.system)) for (const b of j.system) push(b);
40	  if (Array.isArray(j?.messages)) for (const m of j.messages) if (Array.isArray(m?.content)) for (const b of m.content) push(b);
41	  let seenOrg = false;
42	  for (const s of scopes) {
43	    if (s === "org") seenOrg = true;
44	    else if (seenOrg) return true; // a global block found after a narrower one
45	  }
46	  return false;
47	}
48	
49	function startMock(port, { rejectProbe = false, delayProbeMs = 0 } = {}) {
50	  let real = null;
51	  let probe = null;
52	  const server = http.createServer((req, res) => {
53	    let body = ""; req.on("data", (c) => (body += c));
54	    req.on("end", () => {
55	      let j = null; try { j = JSON.parse(body); } catch {}
56	      const beta = req.headers["anthropic-beta"] || "";
57	      const isProbe = j?.system?.[0]?.text?.startsWith("You are Claude Code") && j?.messages?.[0]?.content === "hi";
58	      const reject = (message) => {
59	        res.writeHead(400, { "content-type": "application/json" });
60	        res.end(JSON.stringify({ type: "error", error: { type: "invalid_request_error", message } }));
61	      };
62	      // Enforce the global-prefix rule for EVERY request (probe + live), mirroring
63	      // Anthropic. This is the regression guard for the scope:"global"-after-org-
64	      // scoped-tools-breakpoint 400 that the toolless fixtures missed.
65	      if (globalPrefixViolation(j)) {
66	        if (isProbe) probe = { beta, cache_control: j?.system?.[0]?.cache_control || null, prefixViolation: true };
67	        reject('`cache_control.scope: "global"` is only valid when every preceding block is also globally scoped. A block with `scope: "global"` was found after content with a narrower cache scope. Note that tool definitions render before `system` blocks.');
68	        return;
69	      }
70	      if (isProbe) {
71	        probe = {
72	          beta,
73	          cache_control: j?.system?.[0]?.cache_control || null,
74	          hasTools: Array.isArray(j?.tools) && j.tools.length > 0,
75	          toolScope: (Array.isArray(j?.tools) ? [...j.tools].reverse().find((t) => t?.cache_control) : null)?.cache_control?.scope || null,
76	        };
77	        if (rejectProbe) { reject("cache_control.ephemeral.scope: Extra inputs are not permitted"); return; }
78	        // Emulate Anthropic's beta-gated schema: a cache_control field is rejected
79	        // unless its gating beta rides along. This is exactly what 400s a probe that
80	        // sends ttl:"1h" without extended-cache-ttl-2025-04-11 (the regression guard
81	        // for the probe/live beta-drift bug).
82	        const cc = j?.system?.[0]?.cache_control || {};
83	        if (cc.ttl && !beta.includes("extended-cache-ttl-2025-04-11")) { reject("cache_control.ttl: Extra inputs are not permitted"); return; }
84	        if (cc.scope && !beta.includes(SCOPE_BETA)) { reject("cache_control.scope: Extra inputs are not permitted"); return; }
85	      }
86	      const respond = () => {
87	        if (!isProbe) real = { body: j, beta };
88	        res.writeHead(200, { "content-type": "application/json" });
89	        res.end(JSON.stringify({ id: "m", type: "message", role: "assistant", content: [{ type: "text", text: "ok" }], model: j?.model || "x", stop_reason: "end_turn", usage: { input_tokens: 1, output_tokens: 1 } }));
90	      };
91	      if (isProbe && delayProbeMs > 0) { setTimeout(respond, delayProbeMs); return; }
92	      respond();
93	    });
94	  });
95	  return new Promise((resolve) => server.listen(port, "127.0.0.1", () => resolve({ server, getReal: () => real, getProbe: () => probe })));
96	}
97	
98	async function bootBridge(bridgePort, mockPort, waitMs = 2200) {
99	  const env = { ...process.env, PORT: String(bridgePort), HOST: "127.0.0.1", BRIDGE_GLOBAL_CACHE: "1", _BRIDGE_OAUTH_TOKEN: "sk-ant-oat-test-token", ANTHROPIC_BASE_URL: `http://127.0.0.1:${mockPort}` };
100	  delete env.ANTHROPIC_API_KEY;
101	  const child = spawn(process.execPath, [join(ROOT, "index.js")], { cwd: ROOT, env, stdio: ["ignore", "pipe", "pipe"] });
102	  let log = ""; child.stdout.on("data", (d) => (log += d)); child.stderr.on("data", (d) => (log += d));
103	  await new Promise((r) => setTimeout(r, waitMs)); // boot + (usually) startup probe
104	  return { child, getLog: () => log };
105	}
